use vstd::prelude::*;

verus! {

/// Spec-level “closeness” predicate:
/// true iff (a - b) is strictly between (-tol) and tol.
///
/// We define it over mathematical integers to avoid machine overflow.
spec fn close_i8_spec(a: i8, b: i8, tol: i8) -> bool {
    let ai: int = a as int;
    let bi: int = b as int;
    let ti: int = tol as int;
    (-ti) < (ai - bi) && (ai - bi) < ti
}

/// Scalar implementation.
fn is_close_i8(a: i8, b: i8, tol: i8) -> (res: bool)
    requires
        tol > 0,
    ensures
        res == close_i8_spec(a, b, tol),
{
    // Compute in i16 to avoid i8 overflow in subtraction/negation.
    let d: i16 = (a as i16) - (b as i16);
    let t: i16 = tol as i16;
    // Note: tol > 0 ensures -t is well-defined and strictly less than t.
    res = (-t) < d && d < t;

    // Bridge to the spec (all comparisons are preserved under widening to int).
    assert(res == close_i8_spec(a, b, tol)) by {
        let ai: int = a as int;
        let bi: int = b as int;
        let ti: int = tol as int;

        // Relate widened expressions.
        assert(d as int == ai - bi);
        assert(t as int == ti);
        assert((-t) as int == -ti);

        // Now the boolean expressions match syntactically.
    }
}

/// Vectorized implementation (like numpy.isclose with strict inequality).
fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> (result: Vec<bool>)
    requires
        a.len() == b.len(),
        a.len() > 0,
        tol > 0,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==>
            result[i] == close_i8_spec(a[i], b[i], tol),
{
    let n = a.len();
    let mut out: Vec<bool> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == a.len(),
            n == b.len(),
            tol > 0,
            out.len() == i,
            forall|j: int| 0 <= j < i as int ==>
                out[j] == close_i8_spec(a[j], b[j], tol),
        decreases n - i,
    {
        let r = is_close_i8(a[i], b[i], tol);

        // Push preserves the element-wise spec for all previous indices,
        // and adds it for the new last index.
        out.push(r);

        assert(out.len() == i + 1);
        assert(out[i as int] == close_i8_spec(a[i], b[i], tol));

        i = i + 1;
    }

    result = out;
}

} // verus!

